<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Sesje i logowania'; ?>
<div class="page-head"><div><p class="eyebrow">Profil</p><h1>Sesje i historia logowań</h1></div><form method="post" action="<?=Html::e(Url::to('/profile/sessions/revoke-others'))?>"><?=Csrf::field()?><button class="button secondary">Wyloguj wszystkie inne sesje</button></form></div>
<section class="card section-card"><h2>Aktywne sesje</h2><?php foreach($sessions as $s):?><div class="list-row"><div><strong><?=Html::e($s['is_current']?'Bieżąca sesja':($s['ip_address']?:'Nieznany adres'))?></strong><small><?=Html::e($s['user_agent']?:'Nieznana przeglądarka')?> · ostatnio <?=Html::e($s['last_seen_at'])?><?=$s['revoked_at']?' · unieważniona':''?></small></div><?php if(!$s['is_current']&&!$s['revoked_at']):?><form method="post" action="<?=Html::e(Url::to('/profile/sessions/'.$s['id'].'/revoke'))?>"><?=Csrf::field()?><button class="link-button danger-text">Wyloguj</button></form><?php endif;?></div><?php endforeach;?></section>
<section class="card section-card"><h2>Historia logowań</h2><table><thead><tr><th>Data</th><th>Adres IP</th><th>Przeglądarka</th><th>Wynik</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=Html::e($h['created_at'])?></td><td><?=Html::e($h['ip_address'])?></td><td><?=Html::e($h['user_agent'])?></td><td><span class="badge <?=$h['success']?'ok':'bad'?>"><?=$h['success']?'Sukces':'Niepowodzenie'?></span></td></tr><?php endforeach;?></tbody></table></section>
